"use client";

import {
  ArrowLeftOutlined,
  InboxOutlined,
  PlusOutlined,
} from "@ant-design/icons";
import {
  Alert,
  Button,
  Card,
  ConfigProvider,
  Form,
  Input,
  InputNumber,
  message,
  Space,
  Typography,
  Upload,
  type UploadFile,
} from "antd";
import { useRouter } from "next/navigation";
import { useEffect, useRef, useState } from "react";
import { createOrder, getPendingOrderCreationNotice } from "../api";
import styles from "./orderCreate.module.css";

const { Text, Title } = Typography;
const { TextArea } = Input;

type OrderFormValues = {
  seller?: string;
  totalPrice?: number | null;
  remark?: string;
};

const MAX_IMAGE_SIZE_BYTES = 10 * 1024 * 1024;
const ALLOWED_IMAGE_TYPES = new Set(["image/jpeg", "image/png", "image/webp"]);

export function OrderCreatePage() {
  const router = useRouter();
  const [form] = Form.useForm<OrderFormValues>();
  const [messageApi, messageContextHolder] = message.useMessage();
  const [submitting, setSubmitting] = useState(false);
  const submissionLocked = useRef(false);
  const [pendingNotice, setPendingNotice] = useState<string>();
  const [error, setError] = useState<string>();
  const [billImageFiles, setBillImageFiles] = useState<UploadFile[]>([]);
  const [productImageFiles, setProductImageFiles] = useState<UploadFile[]>([]);
  const [billImageError, setBillImageError] = useState<string>();
  const [productImageError, setProductImageError] = useState<string>();

  useEffect(() => {
    // Read browser storage after hydration; do not update an unmounted form.
    let active = true;
    Promise.resolve().then(() => {
      if (active) setPendingNotice(getPendingOrderCreationNotice());
    });
    return () => { active = false; };
  }, []);

  const submitOrder = async (values: OrderFormValues): Promise<void> => {
    if (submissionLocked.current) return;
    const billImages = getFiles(billImageFiles);
    const productImages = getFiles(productImageFiles);
    setBillImageError(
      billImages.length === 0 ? "Add at least one bill image." : undefined,
    );
    setProductImageError(
      productImages.length === 0
        ? "Add at least one product image."
        : undefined,
    );
    if (billImages.length === 0 || productImages.length === 0) {
      return;
    }

    submissionLocked.current = true;
    setSubmitting(true);
    setError(undefined);
    setBillImageError(undefined);
    setProductImageError(undefined);
    let completed = false;
    try {
      const response = await createOrder({
        ...values,
        billImages,
        productImages,
      });

      completed = true;
      messageApi.success("Order created.");
      router.push(`/orders/${encodeURIComponent(response.order.id)}`);
    } catch (submitError) {
      setPendingNotice(getPendingOrderCreationNotice());
      setError(
        submitError instanceof Error
          ? submitError.message
          : "Failed to create order.",
      );
    } finally {
      if (!completed) {
        submissionLocked.current = false;
        setSubmitting(false);
      }
    }
  };

  return (
    <ConfigProvider
      theme={{
        token: {
          colorPrimary: "#157347",
          colorBgLayout: "#f3f5f4",
          colorBorderSecondary: "#e1e5e2",
          borderRadius: 6,
          fontFamily: "Arial, Helvetica, sans-serif",
        },
      }}
    >
      {messageContextHolder}
      <div className={styles.appShell}>
        <main className={styles.content}>
          <Button
            className={styles.backButton}
            href="/orders"
            icon={<ArrowLeftOutlined />}
            type="text"
          >
            Orders
          </Button>

          <header className={styles.pageHeader}>
            <Text className={styles.eyebrow}>Order management</Text>
            <Title level={1}>Create order</Title>
          </header>

          <Card className={styles.formCard} title="Order information">
            {pendingNotice && !error ? (
              <Alert
                className={styles.errorAlert}
                title="Previous order needs confirmation"
                description={pendingNotice}
                showIcon
                type="warning"
              />
            ) : null}
            {error ? (
              <Alert
                className={styles.errorAlert}
                title="Order could not be created"
                description={error}
                showIcon
                type="error"
              />
            ) : null}

            <Form<OrderFormValues>
              form={form}
              disabled={submitting}
              layout="vertical"
              name="create-order"
              requiredMark="optional"
              onFinish={submitOrder}
            >
              <Form.Item
                label="Seller"
                name="seller"
                rules={[
                  {
                    max: 100,
                    message: "Seller must be 100 characters or less.",
                  },
                ]}
              >
                <Input autoFocus maxLength={100} placeholder="Seller" />
              </Form.Item>

              <ImageUploadField
                disabled={submitting}
                error={billImageError}
                files={billImageFiles}
                label="Bill images"
                onChange={(files) => {
                  setBillImageFiles(files);
                  if (files.length > 0) setBillImageError(undefined);
                }}
                onRejected={(validationError) =>
                  messageApi.error(validationError)
                }
              />

              <ImageUploadField
                disabled={submitting}
                error={productImageError}
                files={productImageFiles}
                label="Product images"
                onChange={(files) => {
                  setProductImageFiles(files);
                  if (files.length > 0) setProductImageError(undefined);
                }}
                onRejected={(validationError) =>
                  messageApi.error(validationError)
                }
              />

              <Form.Item
                label="Total price"
                name="totalPrice"
                rules={[
                  {
                    type: "number",
                    min: 0,
                    message: "Total price cannot be negative.",
                  },
                ]}
              >
                <InputNumber<number>
                  prefix="฿"
                  className={styles.priceInput}
                  controls={false}
                  min={0}
                  placeholder="0.00"
                  precision={2}
                  step={100}
                />
              </Form.Item>

              <Form.Item
                label="Remark"
                name="remark"
                rules={[
                  {
                    max: 1000,
                    message: "Remark must be 1,000 characters or less.",
                  },
                ]}
              >
                <TextArea
                  autoSize={{ minRows: 4, maxRows: 8 }}
                  maxLength={1000}
                  placeholder="Remark"
                  showCount
                />
              </Form.Item>

              <div className={styles.formActions}>
                <Space wrap>
                  <Button disabled={submitting} href="/orders">
                    Cancel
                  </Button>
                  <Button
                    htmlType="submit"
                    icon={<PlusOutlined />}
                    loading={submitting}
                    type="primary"
                  >
                    {pendingNotice ? "Check saved outcome" : "Create order"}
                  </Button>
                </Space>
              </div>
            </Form>
          </Card>
        </main>
      </div>
    </ConfigProvider>
  );
}

function ImageUploadField({
  disabled,
  error,
  files,
  label,
  onChange,
  onRejected,
}: {
  disabled: boolean;
  error?: string;
  files: UploadFile[];
  label: string;
  onChange: (files: UploadFile[]) => void;
  onRejected: (error: string) => void;
}) {
  return (
    <Form.Item
      label={label}
      required
      validateStatus={error ? "error" : undefined}
      help={error}
    >
      <Upload.Dragger
        accept="image/jpeg,image/png,image/webp"
        beforeUpload={(file) => {
          if (!ALLOWED_IMAGE_TYPES.has(file.type)) {
            onRejected(`${file.name} is not a supported image.`);
            return Upload.LIST_IGNORE;
          }
          if (file.size > MAX_IMAGE_SIZE_BYTES) {
            onRejected(`${file.name} is larger than 10 MB.`);
            return Upload.LIST_IGNORE;
          }
          return false;
        }}
        disabled={disabled}
        fileList={files}
        listType="picture"
        maxCount={10}
        multiple
        onChange={({ fileList }) => onChange(fileList)}
      >
        <p className="ant-upload-drag-icon">
          <InboxOutlined />
        </p>
        <p className="ant-upload-text">Upload {label.toLowerCase()}</p>
        <p className="ant-upload-hint">
          JPEG, PNG, or WebP. Maximum 10 MB per image.
        </p>
      </Upload.Dragger>
    </Form.Item>
  );
}

function getFiles(files: UploadFile[]): File[] {
  return files.flatMap((file) =>
    file.originFileObj ? [file.originFileObj] : [],
  );
}

